function automatic int beat_bytes(input int size);
  return 1 << size;
endfunction

function automatic logic [ADDR_W-1:0] aligned_addr(input logic [ADDR_W-1:0] a, input int size);
  return a & ~((1 << size) - 1);
endfunction

function automatic int expected_downstream_len(
    input logic [ADDR_W-1:0] addr,
    input int size,
    input int len);
  int total_bytes;
  int dsize;
  logic [ADDR_W-1:0] first, last;
  logic [ADDR_W-1:0] aligned_first, aligned_last;
  total_bytes = (len + 1) * beat_bytes(size) - (addr - aligned_addr(addr, size));
  first = addr;
  last = addr + total_bytes - 1;
  dsize = (size < 1) ? size : 1;
  aligned_first = aligned_addr(first, dsize);
  aligned_last = aligned_addr(last, dsize);
  return (aligned_last - aligned_first) / beat_bytes(dsize);
endfunction
```

