  endtask

  task automatic wait_u_b(output bit ok, output b_beat_t b);
    ok = 1'b0;
    for (int i = 0; i < MAX_CYCLES; i++) begin
      if (u_b_q.size() > 0) begin
        b = u_b_q.pop_front();
        ok = 1'b1;
        return;
      end
