  task automatic wait_u_r(output bit ok, output r_beat_t r);
    ok = 1'b0;
    for (int i = 0; i < MAX_CYCLES; i++) begin
      if (u_r_q.size() > 0) begin
        r = u_r_q.pop_front();
        ok = 1'b1;
        return;
      end
      @(posedge clk);
    end
  endtask

  // Main test
